#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=7

# This wizard writes .env and then runs `just`, so it has to stand in the repo root.
REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$REPO_ROOT"
if [[ ! -f justfile || ! -f pyproject.toml ]]; then
  printf 'This wizard belongs to the care-task-agent repo, and there is no justfile here.\n' >&2
  exit 1
fi

banner "care-task-agent → Google Cloud"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "gcloud: sign in"
if gcloud auth print-access-token >/dev/null 2>&1; then
  say "Signed in as $(gcloud config get-value account 2>/dev/null || echo unknown), and the credential works."
  if confirm "Sign in as a different account?"; then
    pause "Press Enter to open the browser"
    gcloud auth login
  fi
else
  say "No usable credential is stored — gcloud ignores an expired one."
  say "gcloud opens a browser; sign in with the account that owns your project."
  pause "Press Enter to open the browser"
  gcloud auth login
fi

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Project and billing"
say "The project to bill for Vertex and Cloud Run. It needs billing enabled."
current_project="$(gcloud config get-value project 2>/dev/null || true)"
if [[ -n "$current_project" && "$current_project" != "(unset)" ]]; then
  note "gcloud's current project is $current_project"
fi
step "List your projects:  gcloud projects list --format='value(projectId)'"
step "Or create one:       https://console.cloud.google.com/projectcreate"
ask GOOGLE_CLOUD_PROJECT "Project id:"
if [[ -z "$GOOGLE_CLOUD_PROJECT" ]]; then
  warn "no project id, so nothing below can work — stopping here"
  exit 1
fi
gcloud config set project "$GOOGLE_CLOUD_PROJECT"
write_env GOOGLE_CLOUD_PROJECT "$GOOGLE_CLOUD_PROJECT"
billing="$(gcloud billing projects describe "$GOOGLE_CLOUD_PROJECT" --format='value(billingEnabled)' 2>/dev/null || true)"
if [[ "$billing" == "True" ]]; then
  say "billing is enabled on $GOOGLE_CLOUD_PROJECT"
else
  warn "billing is not enabled on $GOOGLE_CLOUD_PROJECT — Vertex and Cloud Run both need it"
  # Vertex answers 403 BILLING_DISABLED without this, and no amount of auth fixes it.
  if [[ -z "$(gcloud billing accounts list --format='value(name)' 2>/dev/null || true)" ]]; then
    note "no billing account is visible to this identity, so there is nothing to link yet"
    open_url "https://console.cloud.google.com/billing/create"
    pause "Press Enter once you have a billing account and it is linked to $GOOGLE_CLOUD_PROJECT"
  else
    open_url "https://console.cloud.google.com/billing/linkedaccount?project=$GOOGLE_CLOUD_PROJECT"
    pause "Press Enter once billing is linked"
  fi
fi

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Enable the APIs"
say "Vertex AI runs the model. Cloud Run and Artifact Registry run the deploy."
note "Takes about a minute, and is idempotent: already-enabled services are left alone."
if ! command -v docker >/dev/null 2>&1; then
  warn "docker is not on PATH — 'just up' builds the image locally and needs it"
fi
pause "Press Enter to enable them"
gcloud services enable \
  aiplatform.googleapis.com \
  run.googleapis.com \
  artifactregistry.googleapis.com
say "enabled on $GOOGLE_CLOUD_PROJECT"

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Application Default Credentials"
say "Vertex AI reads these. They are a separate credential from the gcloud login,"
say "and land at ~/.config/gcloud/application_default_credentials.json."
say "Grant every scope on the consent screen, and check which account it names:"
say "if Google returns fewer scopes than asked, gcloud dies with"
say "'Scope has changed from … to …' — see docs/API-NOTES.md, divergence 9."
pause "Press Enter to open the browser"
gcloud auth application-default login
gcloud auth application-default set-quota-project "$GOOGLE_CLOUD_PROJECT" \
  || warn "could not set the ADC quota project (harmless for a local run)"
if gcloud auth application-default print-access-token >/dev/null 2>&1; then
  say "the credential works"
else
  warn "the credential does not work — re-run this stage before going on"
fi

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Region, model, and where the records come from"
default_region="$(gcloud config get-value compute/region 2>/dev/null || true)"
if [[ -z "$default_region" || "$default_region" == "(unset)" ]]; then
  default_region="us-central1"
fi
ask GOOGLE_CLOUD_REGION "Vertex region [${default_region}]:"
if [[ -z "$GOOGLE_CLOUD_REGION" ]]; then
  GOOGLE_CLOUD_REGION="$default_region"
fi
write_env GOOGLE_CLOUD_REGION "$GOOGLE_CLOUD_REGION"

ask MODEL_ID "Model id [gemini-2.5-flash]:"
if [[ -z "$MODEL_ID" ]]; then
  MODEL_ID="gemini-2.5-flash"
fi
write_env MODEL_ID "$MODEL_ID"
note "the id is a guess until \`just demo\` proves it — see docs/API-NOTES.md"

ask FHIR_BASE_URL "FHIR base URL [https://launch.smarthealthit.org/v/r4/fhir]:"
if [[ -z "$FHIR_BASE_URL" ]]; then
  FHIR_BASE_URL="https://launch.smarthealthit.org/v/r4/fhir"
fi
write_env FHIR_BASE_URL "$FHIR_BASE_URL"
note "the SMART sandbox returns patients with appointments, medications and tasks;"
note "hapi.fhir.org returns whatever is public that day."

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "The tool server's shared secret"
say "The agent authenticates to the tool server with this, which keeps the server off"
say "the open internet. It is slice-grade, not per-caller identity (docs/API-NOTES.md)."
if [[ -n "$(_existing MCP_AUTH_TOKEN || true)" ]]; then
  ask_secret MCP_AUTH_TOKEN "MCP shared secret:"
else
  MCP_AUTH_TOKEN="$(openssl rand -hex 32)"
  say "generated a fresh 32-byte secret"
fi
write_env MCP_AUTH_TOKEN "$MCP_AUTH_TOKEN"
note "\`just up\` reuses this value, so the deployed tool server and your local run agree"

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Verify"
say "The offline half needs none of this — no model, no network, no cloud:"
pause "Press Enter to run: just verify"
just verify
say "The live half needs the tool server running. In another terminal:"
step "just mcp          # leave it running; it serves 127.0.0.1:8765/mcp"
pause "Press Enter once the tool server is up"
if confirm "Ask one live question now (just demo)?"; then
  just demo
fi
if confirm "Run the whole live task set (just eval)?"; then
  just eval
fi
if confirm "Deploy both services to Cloud Run (just up)? This creates billable services."; then
  just up
fi

finish
}

run_wizard "$@"; exit
